\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{document}

\pagestyle{empty} %% IMPORTANT


\begin{tikzpicture}
\def\gcolor{deepskyblue}

\begin{axis}[
legend pos=outer north east,
tick style={line width=0.8pt, color=black},
label style={font=\small},
legend style={font=\footnotesize},
axis line style = thick,
axis y line = center,
axis x line = middle,
%axis equal,
%grid = both,
xmin = -6,
xmax = 6,
ymin = -3.5,
ymax = 3.5,
%yticklabels={,,},
%xticklabels={,,},
   xtick={
        -6.28318, -4.7123889, -3.14159, -1.5708,
        1.5708, 3.14159, 4.7123889, 6.28318
    },
    xticklabels={
        $-2\pi$, $-\frac {3\pi} 2$, $-\pi$, $-\frac \pi 2$,
        $\frac \pi 2$, $\pi$, $\frac {3\pi} 2$, $2\pi$
    },
ytick = {-1,1},
yticklabels ={$-1$,$1$},
yticklabel style={xshift=0.08cm, font=\small},
xlabel = $x$,
ylabel = {$y$},
xlabel style={below right},
ylabel style={above left}
]

\addplot [
domain=-3.1:-0.1,
samples=100,
color=\gcolor,
line width=1.2pt,
]{cosec(deg(x))};

\addplot [
domain=0.1:3,
samples=100,
color=\gcolor,
line width=1.2pt,
]{cosec(deg(x))};

\addplot [
domain=3.3:6.1,
samples=100,
color=\gcolor,
line width=1.2pt,
]{cosec(deg(x))};

\addplot [
domain=-6.1:-3.3,
samples=100,
color=\gcolor,
line width=1.2pt,
]{cosec(deg(x))};


\addplot[color=black,opacity=0.5, dashed, line width=0.6pt] coordinates {(3.14,0) (3.14,10)};
\addplot[color=black,opacity=0.5, dashed, line width=0.6pt] coordinates {(-3.14,0) (-3.14,10)};
\addplot[color=black,opacity=0.5, dashed, line width=0.6pt] coordinates {(-6.28,0) (-6.28,10)};
\addplot[color=black,opacity=0.5, dashed, line width=0.6pt] coordinates {(6.28,0) (6.28,10)};

\addplot[color=black,opacity=0.5, dashed, line width=0.6pt] coordinates {(3.14,-10) (3.14,-0.8)};
\addplot[color=black,opacity=0.5, dashed, line width=0.6pt] coordinates {(-3.14,-10) (-3.14,-0.8)};
\addplot[color=black,opacity=0.5, dashed, line width=0.6pt] coordinates {(-6.28,-10) (-6.28,-0.8)};
\addplot[color=black,opacity=0.5, dashed, line width=0.6pt] coordinates {(6.28,-10) (6.28,-0.8)};

\end{axis}
\end{tikzpicture}
\end{document}

